def remove_dups_set(a: list[int]) -> int:
    uniq = sorted(set(a))
    a[: len(uniq)] = uniq
    return len(uniq)

def remove_duplicates(a: list[int]) -> int:
    if not a:
        return 0
    i = 0
    for j in range(1, len(a)):
        if a[j] != a[i]:
            i += 1
            a[i] = a[j]
    return i + 1
